+    fn deposit_step(
+        circ: &mut Circuit,
+        i: usize,
+        ctrls: &[&QReg],
+        pos: &[QReg],
+        flag: Option<&QReg>,
+        n: usize,
+    ) {
+        if i >= n {
+            return; // i == n is the empty (k = -1) layer
+        }
+        let k = n - 1 - i;
+        let gd = k ^ (k + 1);
+        let bits: Vec<usize> = (0..pos.len()).filter(|&b| (gd >> b) & 1 == 1).collect();
